def paths(n,env,files=None):
    o,c,r=case(n,files or {}, ['--print-id'], env=env, dbg=True)
    for l in o[2].splitlines():
        if 'XTE__CONFIGS' in l or 'XTE__APPLICATIONS_DIRS' in l: print(n, l.replace('$ROOT','R'))
